import {escapeText} from "fwtoolkit"

import type {FidusNode} from "../../types.js"

export function convertTexts(nodeList: FidusNode[]): string {
    return nodeList.map(node => convertText(node)).join("")
}

export function convertText(node: FidusNode): string {
    let start = ""
    let end = ""
    let strong, em, underline, hyperlink, anchor, sup, sub, code
    // Check for hyperlink, bold/strong, italic/em and underline
    if (node.marks) {
        strong = node.marks.find(mark => mark.type === "strong")
        em = node.marks.find(mark => mark.type === "em")
        underline = node.marks.find(mark => mark.type === "underline")
        hyperlink = node.marks.find(mark => mark.type === "link")
        anchor = node.marks.find(mark => mark.type === "anchor")
        sup = node.marks.find(mark => mark.type === "sup")
        sub = node.marks.find(mark => mark.type === "sub")
        code = node.marks.find(mark => mark.type === "code")
    }
    let attrs = anchor ? ` id="${anchor.attrs?.id}"` : ""
    if (em) {
        start += `<italic${attrs}>`
        end = "</italic>" + end
        attrs = ""
    }
    if (strong) {
        start += `<bold${attrs}>`
        end = "</bold>" + end
        attrs = ""
    }
    if (underline) {
        start += `<underline${attrs}>`
        end = "</underline>" + end
        attrs = ""
    }
    if (sup) {
        start += `<sup${attrs}>`
        end = "</sup>" + end
        attrs = ""
    }
    if (sub) {
        start += `<sub${attrs}>`
        end = "</sub>" + end
        attrs = ""
    }
    if (code) {
        start += `<monospace${attrs}>`
        end = "</monospace>" + end
        attrs = ""
    }
    if (hyperlink) {
        const href = (hyperlink.attrs?.href as string) || ""
        const title = (hyperlink.attrs?.title as string) || ""
        if (href[0] === "#") {
            // Internal link
            start += `<xref rid="${href.substring(1)}"${attrs}>`
            end = "</xref>" + end
        } else {
            // External link
            start += `<ext-link xlink:href="${escapeText(href)}" ext-link-type="uri" xlink:title="${escapeText(title)}"${attrs}>`
            end = "</ext-link>" + end
        }
        attrs = ""
    }
    if (attrs) {
        start += `<named-content${attrs}>`
        end = "</named-content>" + end
        attrs = ""
    }
    return start + escapeText(node.text || "") + end
}
